quests[63866] = { id = 63866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Claiming the Light", description = "Take this vessel, {name}. Invoking its magic will allow you to take this creature's power and claim it for yourself. With it, you will be able to restore your fallen comrade to life.\n\nThere are those who would say what we're doing is wrong, but much of what has befallen us is also wrong. Would they have us throw away such a gift?\n\nThey do not complain when our power is used to prevent the further destruction of Silvermoon. No, they object when they are safe from harm and indulging their magic addictions.", sourceObjective = "Use the Shimmering Vessel on M'uru to fill it and return to Knight-Lord Bloodvalor in Silvermoon City.", progress = "Have you spoken with Magister Astalor Bloodsworn?", completion = "Well done, {name}. The powers granted by the Light have never come 'naturally' to the Blood Knights, but we are not so weak-willed as to let nature dictate to us.\n\nOur mastery of the arcane has provided a path to help see us through these harsh times. Power no longer flows freely in these halls, but it is there for the tenacious and strong of will. Few have the stomach or the aptitude to master it these days, but I know you will not disappoint the order.", sourceObjectiveStatus = "unverified-source-field" }
quests[63978] = { id = 63978, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cloak and Daggers", description = "As a Rogue, you specialize in striking from the shadows, dispatching foes with a variety of poisons and bleeding attacks. Use Stealth to sneak around and then speak with me when your ready for more training.", sourceObjective = "Use Stealth to sneak around.", sourceObjectiveStatus = "unverified-source-field" }
quests[64028] = { id = 64028, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Beginning", description = "A letter magically appears in the lining of your armor. It reads:\n\n\"Welcome to the city of Stormwind, capital of the Alliance! \n\nMeet with a {class} trainer to begin your training. They will help prepare you for your journey across Azeroth and beyond.\"", sourceObjective = "Meet with a {class} trainer in Stormwind.", completion = "Ready for your training, {race}?", sourceObjectiveStatus = "unverified-source-field" }
quests[64031] = { id = 64031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tools for Survival", description = "Before we begin, you need to be equipped with weapons and armor suited to your talents. The life of an adventurer is never dull, and you never know what will happen next!\n\nI've prepared a survival kit for your adventures. It contains additional weapons, armor, and rations. I trust that you will make use of it well.", sourceObjective = "Open the survival kit and equip a weapon.", completion = "You look prepared! Let us move onto your first lesson in combat training.", sourceObjectiveStatus = "unverified-source-field" }
quests[64034] = { id = 64034, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Combat Training", description = "As you grow in power, so does your capabilities of being a skillful {class}.\n\nYou can find trainers all around Azeroth, and in capital cities such as here in Stormwind, Darnassus, or Ironforge.\n\nThere's a price to this knowledge, but I will reimburse you just this once. When you are ready, speak with me again to train your abilities.", sourceObjective = "Train a spell by speaking to a {class} trainer.", progress = "When you are ready, speak with me again to train your abilities.", completion = "You look stronger already, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[64035] = { id = 64035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talented", description = "Every {class} makes use of different abilities, talents and capabilities. We differ from each other in that we have unique interests and inclinations.\n\nWhen you level up in power, you can enhance and specialize your abilities through your talents, without the instruction of a trainer.\n\nIf you change your mind on these talents, you can speak with a {class} trainer to rework them.", sourceObjective = "Activate the Talents interface and allocate 5 Talent Points.", completion = "You're ready for battle, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[64037] = { id = 64037, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eastern Plaguelands", description = "By the order of Highlord Bolvar Fordragon, all able-bodied citizens of the Alliance are to report to Lord Barthalomew at Light's Hope Chapel.\n\nThe Argent Dawn needs your help to win back the Eastern Plaguelands from the grasp of the scourge.\n\nTo reach the Eastern Plaguelands, speak to the Gryphon Master, Dungar Longdrink, and his gryphons can get you there faster than even the swiftest horse.\n\nFor the glory and honor of the Alliance!", sourceObjective = "Travel to the Eastern Plaguelands and find Leonid Barthalomew. He awaits your arrival at Light's Hope Chapel.", completion = "Perhaps you can help, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[64038] = { id = 64038, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Portal", description = "There exists a hellish gate that has loomed silent for years, but it is silent no longer.\n\nBy the order of Highlord Bolvar Fordragon, all able-bodied citizens of the Alliance are to report to the Blasted Lands. Speak to Dungar Longdrink, the Gryphon Master to arrange a flight.\n\nOnce at the Blasted Lands, report to Watch Commander Relthorn Netherwane. He awaits you before the Dark Portal...", sourceObjective = "Find Watch Commander Relthorn Netherwane at the Blasted Lands. He awaits your arrival before the Dark Portal.", completion = "Welcome to the nightmare!", sourceObjectiveStatus = "unverified-source-field" }
quests[64046] = { id = 64046, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Beginning", description = "A letter magically appears in the lining of your armor. It reads:\n\n\"Welcome to Orgrimmar, capital of the Horde!\n\nMeet with a {class} trainer to begin your training. They will help prepare you for your journey across Azeroth and beyond.\"", sourceObjective = "Meet with a {class} trainer in Orgrimmar.", completion = "Ready for your training, {race}?", sourceObjectiveStatus = "unverified-source-field" }
quests[64047] = { id = 64047, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Beginning", description = "A letter magically appears in the lining of your armor. It reads:\n\n\"Welcome to Thunder Bluff, capital to the Tauren!\n\nMeet with a {class} trainer to begin your training. They will help prepare you for your journey across Azeroth and beyond.\"", sourceObjective = "Meet with a {class} trainer in Thunder Bluff.", completion = "Ready for your training?", sourceObjectiveStatus = "unverified-source-field" }
