quests[72238] = { id = 72238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrath (80) E" }
quests[72522] = { id = 72522, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Festering Emerald Drake", sourceObjective = "Greetings {name}, I've been expecting you. An acquaintance of mine asked me to give you these items when you stopped by. He mentioned something about a reward for a purchase you made from some mutual friends.\n\nMaybe you know what he meant?\n\nAnyway, here's your reward. Oh, one more thing. My acquaintance, Landro Longshot, said that if you ever lose an item, you can find him on the docks in Booty Bay to get a replacement.", sourceObjectiveStatus = "unverified-source-field" }
quests[72523] = { id = 72523, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Festering Emerald Drake", sourceObjective = "Ah, yes. I'm glad you finally showed up to take this package off my hands.\n\nOur mutual friends wanted you to have these rewards in exchange for a purchase you made. That's none of my business though. I'm just the delivery boy on this deal.\n\nIf you ever lose any of these items, come back and I'll give you a replacement, no charge.", sourceObjectiveStatus = "unverified-source-field" }
quests[74940] = { id = 74940, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flurky", sourceObjective = "Greetings {name}, I've been expecting you. An acquaintance of mine asked me to give you these items when you stopped by. He mentioned something about a reward for a purchase you made from some mutual friends.\n\nMaybe you know what he meant?\n\nAnyway, here's your reward. Oh, one more thing. My acquaintance, Landro Longshot, said that if you ever lose an item, you can find him on the docks in Booty Bay to get a replacement.", sourceObjectiveStatus = "unverified-source-field" }
quests[74941] = { id = 74941, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flurky", sourceObjective = "Ah, yes. I'm glad you finally showed up to take this package off my hands.\n\nOur mutual friends wanted you to have these rewards in exchange for a purchase you made. That's none of my business though. I'm just the delivery boy on this deal.\n\nIf you ever lose any of these items, come back and I'll give you a replacement, no charge.", sourceObjectiveStatus = "unverified-source-field" }
quests[75491] = { id = 75491, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glub", sourceObjective = "Greetings {name}, I've been expecting you. An acquaintance of mine asked me to give you these items when you stopped by. He mentioned something about a reward for a purchase you made from some mutual friends.\n\nMaybe you know what he meant?\n\nAnyway, here's your reward. Oh, one more thing. My acquaintance, Landro Longshot, said that if you ever lose an item, you can find him on the docks in Booty Bay to get a replacement.", sourceObjectiveStatus = "unverified-source-field" }
quests[75492] = { id = 75492, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glub", sourceObjective = "Ah, yes. I'm glad you finally showed up to take this package off my hands.\n\nOur mutual friends wanted you to have these rewards in exchange for a purchase you made. That's none of my business though. I'm just the delivery boy on this deal.\n\nIf you ever lose any of these items, come back and I'll give you a replacement, no charge.", sourceObjectiveStatus = "unverified-source-field" }
quests[78136] = { id = 78136, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Beginning", description = "A letter magically appears in the lining of your armor. It reads:\n\n\"Welcome to the city of Stormwind, capital of the Alliance! \n\nMeet with a {class} trainer to begin your training. They will help prepare you for your journey across Azeroth and beyond.\"", sourceObjective = "Meet with a {class} trainer in Stormwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[78137] = { id = 78137, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Beginning", description = "A letter magically appears in the lining of your armor. It reads:\n\n\"Welcome to Orgrimmar, capital of the Horde!\n\nMeet with a {class} trainer to begin your training. They will help prepare you for your journey across Azeroth and beyond.\"", sourceObjective = "Meet with a {class} trainer in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[78138] = { id = 78138, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Beginning", description = "A letter magically appears in the lining of your armor. It reads:\n\n\"Welcome to Thunder Bluff, capital to the Tauren!\n\nMeet with a {class} trainer to begin your training. They will help prepare you for your journey across Azeroth and beyond.\"", sourceObjective = "Meet with a {class} trainer in Thunder Bluff.", sourceObjectiveStatus = "unverified-source-field" }
quests[78140] = { id = 78140, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tools for Survival", description = "Before we begin, you need to be equipped with weapons and armor suited to your talents. The life of an adventurer is never dull, and you never know what will happen next!\n\nI've prepared a survival kit for your adventures. It contains additional weapons, armor, and rations. I trust that you will make use of it well.", sourceObjective = "Open the survival kit and equip a weapon.", sourceObjectiveStatus = "unverified-source-field" }
quests[78151] = { id = 78151, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tools for Survival", description = "Before we begin, you need to be equipped with weapons and armor suited to your talents. The life of an adventurer is never dull, and you never know what will happen next!\n\nI've prepared a survival kit for your adventures. It contains additional weapons, armor, and rations. I trust that you will make use of it well.", sourceObjective = "Open the survival kit and equip a weapon.", sourceObjectiveStatus = "unverified-source-field" }
quests[78157] = { id = 78157, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Combat Training", description = "As you grow in power, so does your capabilities of being a skillful {class}.\n\nYou can find trainers all around Azeroth, and in capital cities such as here in Stormwind, Darnassus, or Ironforge.\n\nThere's a price to this knowledge, but I will reimburse you just this once. When you are ready, speak with me again to train your abilities.", sourceObjective = "Train a spell by speaking to a {class} trainer.", sourceObjectiveStatus = "unverified-source-field" }
quests[78158] = { id = 78158, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Combat Training", description = "As you grow in power, so does your capabilities of being a skillful {class}.\n\nYou can find trainers all around Azeroth, and in capital cities such as here in Orgrimmar, Thunder Bluff, or the Undercity.\n\nThere's a price to this knowledge, but I will reimburse you just this once. When you are ready, speak with me again to train your abilities.", sourceObjective = "Train a spell by speaking to a {class} trainer.", sourceObjectiveStatus = "unverified-source-field" }
quests[78164] = { id = 78164, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talented", description = "Every {class} makes use of different abilities, talents and capabilities. We differ from each other in that we have unique interests and inclinations.\n\nWhen you level up in power, you can enhance and specialize your abilities through your talents, without the instruction of a trainer.\n\nIf you change your mind on these talents, you can speak with a {class} trainer to rework them.", sourceObjective = "Activate the Talents interface and allocate 5 Talent Points.", sourceObjectiveStatus = "unverified-source-field" }
quests[78165] = { id = 78165, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talented", description = "Every {class} makes use of different abilities, talents and capabilities. We differ from each other in that we have unique interests and inclinations.\n\nWhen you level up in power, you can enhance and specialize your abilities through your talents, without the instruction of a trainer.\n\nIf you change your mind on these talents, you can speak with a {class} trainer to rework them.", sourceObjective = "Activate the Talents interface and allocate 5 Talent Points.", sourceObjectiveStatus = "unverified-source-field" }
quests[78166] = { id = 78166, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Northrend", description = "The Lich King must pay for the atrocities he has unleashed across our lands!\n\nBy the order of King Varian Wrynn, you have been called upon to take arms and aid in the Alliance's campaign in defeating the Lich King!", sourceObjective = "Use the scroll of teleportation from your inventory to reach Northrend and speak to the Image of Archmage Modera.", sourceObjectiveStatus = "unverified-source-field" }
quests[78167] = { id = 78167, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talented", description = "Every {class} makes use of different abilities, talents and capabilities. We differ from each other in that we have unique interests and inclinations.\n\nWhen you level up in power, you can enhance and specialize your abilities through your talents, without the instruction of a trainer.\n\nIf you change your mind on these talents, you can speak with a {class} trainer to rework them.", sourceObjective = "Activate the Talents interface and allocate 5 Talent Points.", sourceObjectiveStatus = "unverified-source-field" }
quests[78168] = { id = 78168, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Northrend", description = "The Lich King must pay for the atrocities he has unleashed across our lands!\n\nBy the order of Warchief Thrall, you have been called upon to take arms and aid in the Horde's campaign in defeating the Lich King!", sourceObjective = "Use the scroll of teleportation from your inventory to reach Northrend and speak to the Image of Archmage Aethas Sunreaver.", sourceObjectiveStatus = "unverified-source-field" }
quests[78219] = { id = 78219, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Beginning", description = "A letter magically appears in the lining of your armor. It reads:\n\n\"Welcome to Acherus: The Ebon Hold, the sanctuary for all Death Knights who denounce the Lich King!\"\n\nMeet with a {class} trainer to begin your training. They will help prepare you for your journey across Azeroth and beyond.\"", sourceObjective = "Meet with a {class} trainer in Acherus: The Ebon Hold.", sourceObjectiveStatus = "unverified-source-field" }
