quests[78752] = { id = 78752, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Demise: Titan Rune Protocol Gamma", description = "The Lich King's presence mustn't extend any further! \n\nThe Council of Six has decreed that any strong enough fighter should take up arms and aid in keeping Azeroth safe!", sourceObjective = "Archmage Lan'dalock in Dalaran wants you to return with the Defiler's Medallion from any final dungeon boss. \n\nThis quest may only be completed on any Titan Rune Protocol Gamma dungeon difficulty.", progress = "We speak again, {name}. Does this mean you were successful with your duties?", completion = "What evil lies within this!  I will bring this back to \n\nThe Council of Six to investigate further.", sourceObjectiveStatus = "unverified-source-field" }
quests[78753] = { id = 78753, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Demise: Threats to Azeroth", description = "We must continue putting pressure on all fronts!\n\nThe Council of Six has decreed that any willing fighter should take up arms and aid in keeping Azeroth safe!", sourceObjective = "Archmage Lan'dalock in Dalaran wants you to return with the Mysterious Artifact from any final dungeon boss. \n\nThis quest may only be completed on any Heroic dungeon difficulty.", progress = "Is something the matter? Why have you not dispatched any of these threats?", completion = "What an interesting find! I will bring this back to \n\nThe Council of Six to investigate further.", sourceObjectiveStatus = "unverified-source-field" }
